		pluginSidebarQaDesc: "Markera-och-fråga: Markera konversationstext → fråga i högra panelen → en dedikerad följdfrågesession (❓ följdfråga) i samma arbetsyta; en snabb no-thinking-modell komprimerar huvudkontexten och injicerar den tillsammans med citatet, utan att avbryta huvudkonversationen. Följdfrågor kan nästlas, fortsättas och arkiveras",
		pluginSidenoteDesc: "Side chat i Codex-stil + anteckningar på markeringar: forka den aktuella sessionen till en beständig sidopanel (arkiveras ut ur sessionslistan, flera instanser, kommandot /side, överlever omladdning, modellen följer huvudsessionen); markera assistant-text → numrerad badge + anteckningsredigerare → ett \"N anteckningar\"-chip som följer med nästa meddelande, eller ställ frågan direkt i en side chat",
